import{_ as t,o as a,c as o,a8 as s}from"./chunks/framework.R_sesYpn.js";const h=JSON.parse('{"title":"Functions","description":"","frontmatter":{},"headers":[],"relativePath":"guide/query-language/functions.md","filePath":"guide/040_query-language/018_functions.md","lastUpdated":1783937378000}'),i={name:"guide/query-language/functions.md"};function n(c,e,r,d,u,l){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="functions" tabindex="-1">Functions <a class="header-anchor" href="#functions" aria-label="Permalink to &quot;Functions&quot;">​</a></h1> <p>BCQL supports a number of useful functions. Some functions produce queries as output, which you can use as part of a larger query; others produce values that you can pass to other functions.</p> <p>Some of these functions exist in some form in other dialects of Corpus Query Language.</p> <p>Functions to do with relations search are described <a href="./relations.html">there</a>.</p> <h2 id="query-functions" tabindex="-1">Query functions <a class="header-anchor" href="#query-functions" aria-label="Permalink to &quot;Query functions&quot;">​</a></h2> <p>The following functions can be used in the regular query part (before <code>::</code>) to determine or change the hits to find.</p> <h3 id="cspan-adjust-to-capture" tabindex="-1">cspan: adjust to capture <a class="header-anchor" href="#cspan-adjust-to-capture" aria-label="Permalink to &quot;cspan: adjust to capture&quot;">​</a></h3> <div class="warning custom-block"><p class="custom-block-title">In-development feature</p> <p>Try this feature on <code>dev</code> (Docker image or branch). It will be finalized for version <code>5.0</code>.</p></div> <p>Occasionally, you might not want your hits to span your whole query, but you&#39;re just interested in one part of it. You can use the <code>cspan()</code> function to adjust the hit:</p> <div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># Find adjectives with tree</span></span>
<span class="line"><span>cspan(A:[pos=&quot;ADJ&quot;]+ &quot;tree&quot;, &quot;A&quot;)</span></span></code></pre></div><p>The hits will be anything captured as <code>A</code>, so just the adjectives in this case.</p> <p>(of course, the same result can often be achieved using a lookahead. In this case, you could use <code>[pos=&quot;ADJ&quot;]+ (?= &quot;tree&quot;)</code> to get the same hits)</p> <h3 id="meet-nearby-words" tabindex="-1">meet: nearby words <a class="header-anchor" href="#meet-nearby-words" aria-label="Permalink to &quot;meet: nearby words&quot;">​</a></h3> <div class="warning custom-block"><p class="custom-block-title">In-development feature</p> <p>Try this feature on <code>dev</code> (Docker image or branch). It will be finalized for version <code>5.0</code>.</p></div> <p>You can use either the <code>meet</code> or the <code>meet_within</code> function to filter matches based on the presence of other words nearby.</p> <p>For example, to find all occurrences of the word <em>cat</em> that are within 5 tokens of the word <em>fluffy</em> (before or after), you can use:</p> <div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>meet(&quot;cat&quot;, &quot;fluffy&quot;, -5, 5)</span></span></code></pre></div><p>To find occurrences of the phrase <em>black dog</em> with the word <em>good</em> occurring up to 10 tokens before it, use:</p> <div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>meet(&quot;black&quot; &quot;dog&quot;, &quot;good&quot;, -10, -1)</span></span></code></pre></div><p>To find occurrences of the word <em>fish</em> with the phrase <em>in water</em> occurring between 2 and 5 tokens after it (i.e. 1-4 tokens between <em>fish</em> and <em>in</em>):</p> <div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>meet(&quot;fish&quot;, &quot;in&quot; &quot;water&quot;, 2, 5)</span></span></code></pre></div><p>To find occurrences of <code>platypus</code> where <code>weird</code> does NOT occur within 5 tokens:</p> <div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>meet(&quot;platypus&quot;, !&quot;weird&quot;, -5, 5)</span></span></code></pre></div><details class="details custom-block"><summary>How <code>meet</code> works</summary> <p>The <code>meet</code> function was inspired by the function with the same name in the <a href="https://www.sketchengine.eu/documentation/cql-meet-union/" target="_blank" rel="noreferrer">Sketch Engine</a>.</p> <p>Note that the <code>meet</code> function is just syntactic sugar for a &quot;regular&quot; BCQL query. For example, <code>meet(&quot;fish&quot;, &quot;in&quot; &quot;water&quot;, 2, 5)</code> is equivalent to:</p> <div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;fish&quot; (?= []{1,4} &quot;in&quot; &quot;water&quot; )</span></span></code></pre></div><p>(read as: find those occurrences of <em>fish</em> that are followed by 1-4 tokens, followed by the phrase <em>in water</em>)</p> <p>Different calls to <code>meet</code> and <code>meet_within</code> are rewritten to different queries, trying to choose the optimal variant for the situation.</p></details> <h3 id="meet-within-meet-within-boundary" tabindex="-1">meet_within: meet within boundary <a class="header-anchor" href="#meet-within-meet-within-boundary" aria-label="Permalink to &quot;meet_within: meet within boundary&quot;">​</a></h3> <div class="warning custom-block"><p class="custom-block-title">In-development feature</p> <p>Try this feature on <code>dev</code> (Docker image or branch). It will be finalized for version <code>5.0</code>.</p></div> <p>You may only want to find words that occur in the same sentence. This is what <code>meet_within</code> is for. To find <em>cat</em> and <em>fluffy</em> in the same sentence:</p> <div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>meet_within(&quot;cat&quot;, &quot;fluffy&quot;, &lt;s/&gt;)</span></span></code></pre></div><p>To also require that they must occur within 5 words of each other:</p> <div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>meet_within(&quot;cat&quot;, &quot;fluffy&quot;, &lt;s/&gt;, -5, 5)</span></span></code></pre></div><p>To find <em>cat</em> provided that the sentence does not have <em>fluffy</em> within 5 words of it:</p> <div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>meet_within(&quot;cat&quot;, !&quot;fluffy&quot;, &lt;s/&gt;, -5, 5)</span></span></code></pre></div><h3 id="union-combine-matches" tabindex="-1">union: combine matches <a class="header-anchor" href="#union-combine-matches" aria-label="Permalink to &quot;union: combine matches&quot;">​</a></h3> <div class="warning custom-block"><p class="custom-block-title">In-development feature</p> <p>Try this feature on <code>dev</code> (Docker image or branch). It will be finalized for version <code>5.0</code>.</p></div> <p>The <code>union</code> function allows you to combine matches from a list of queries into a single result set. For example, to find all occurrences of either <em>fluffy cat</em> or <em>good dog</em>, use:</p> <div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>union(&quot;fluffy&quot; &quot;cat&quot;, &quot;good&quot; &quot;dog&quot;)</span></span></code></pre></div><p>This is equivalent to the following query using the OR operator (<code>|</code>):</p> <div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;fluffy&quot; &quot;cat&quot; | &quot;good&quot; &quot;dog&quot;</span></span></code></pre></div><p>The function is provided for those familiar with it from other corpus query languages.</p> <h2 id="constraint-functions" tabindex="-1">Constraint functions <a class="header-anchor" href="#constraint-functions" aria-label="Permalink to &quot;Constraint functions&quot;">​</a></h2> <p>These are used in constraints (after <code>::</code>), to operate on parts captured by the query.</p> <h3 id="start-start-of-capture" tabindex="-1">start: start of capture <a class="header-anchor" href="#start-start-of-capture" aria-label="Permalink to &quot;start: start of capture&quot;">​</a></h3> <p>Within constraints, use <code>start(A)</code> to get the starting token position of capture <code>A</code>.</p> <p>If <code>A</code> captured the first token of the document, <code>start(A)</code> would return <code>0</code>.</p> <h3 id="end-end-of-capture" tabindex="-1">end: end of capture <a class="header-anchor" href="#end-end-of-capture" aria-label="Permalink to &quot;end: end of capture&quot;">​</a></h3> <p>Within constraints, use <code>end(A)</code> to get the ending token position of capture <code>A</code>. Note that this is always the first token position AFTER the capture.</p> <p>The first token in a document has token position 0, so if <code>A</code> captured the first two words of the document, <code>end(A)</code> would return <code>2</code> (the third token).</p> <h3 id="gap-gap-between-captures" tabindex="-1">gap: gap between captures <a class="header-anchor" href="#gap-gap-between-captures" aria-label="Permalink to &quot;gap: gap between captures&quot;">​</a></h3> <div class="warning custom-block"><p class="custom-block-title">In-development feature</p> <p>Try this feature on <code>dev</code> (Docker image or branch). It will be finalized for version <code>5.0</code>.</p></div> <p>To determine the gap between two captures:</p> <div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>gap(A, B, directional=false)</span></span></code></pre></div><p>If <code>A</code> and <code>B</code> overlap or are contiguous, this will return 0.</p> <p>Otherwise, if the optional argument <code>directional</code> is <code>false</code> (the default) it will determine the gap between A and B as a non-negative number. (To be precise, it calculates either <code>end(B) - start(A)</code> or <code>end(A) - start(B)</code>, whichever is positive)</p> <p>If <code>directional</code> is set to <code>true</code>, the gap will be negative if <code>A</code> comes after <code>B</code>.</p> <h2 id="working-with-types" tabindex="-1">Working with types <a class="header-anchor" href="#working-with-types" aria-label="Permalink to &quot;Working with types&quot;">​</a></h2> <p>BCQL supports several basic types such as string, integer, boolean and list. These functions create or convert to specific types.</p> <h3 id="abs-absolute-value" tabindex="-1">abs: absolute value <a class="header-anchor" href="#abs-absolute-value" aria-label="Permalink to &quot;abs: absolute value&quot;">​</a></h3> <div class="warning custom-block"><p class="custom-block-title">In-development feature</p> <p>Try this feature on <code>dev</code> (Docker image or branch). It will be finalized for version <code>5.0</code>.</p></div> <p>Calculates the absolute value of a number:</p> <div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>abs(-5)   # result 5</span></span></code></pre></div><h3 id="in-range-test-if-numbers-are-within-a-range" tabindex="-1">in_range: test if numbers are within a range <a class="header-anchor" href="#in-range-test-if-numbers-are-within-a-range" aria-label="Permalink to &quot;in_range: test if numbers are within a range&quot;">​</a></h3> <p>Checks if a number falls within a range (inclusive).</p> <p>To check if capture <code>A</code> starts in the first 100 tokens in the document:</p> <div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>in_range(start(A), 0, 100)</span></span></code></pre></div><p>This would be equivalent to <code>start(A) &gt;= 0 &amp; start(A) &lt;= 100</code>. Using <code>in_range</code> can be convenient if the expression is longer, to avoid having to repeat it.</p> <h3 id="list-list-of-values" tabindex="-1">list: list of values <a class="header-anchor" href="#list-list-of-values" aria-label="Permalink to &quot;list: list of values&quot;">​</a></h3> <div class="warning custom-block"><p class="custom-block-title">In-development feature</p> <p>Try this feature on <code>dev</code> (Docker image or branch). It will be finalized for version <code>5.0</code>.</p></div> <p>Some functions take a list of values as input. You can create such a list using the <code>list</code> function. For example, to pass multiple clauses to the <code>union</code> function, you could use:</p> <div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>union(list(&quot;cat&quot;, &quot;dog&quot;))</span></span></code></pre></div><p>Note that you won&#39;t need <code>list()</code> to pass the function&#39;s final (or in this, only) parameter: anytime the final parameter to a function is of type list, you can simply pass a variable number of arguments and they will automatically be combined into a list. For example:</p> <div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>union(&quot;one&quot;, &quot;two&quot;, &quot;three&quot;)  # same as union(list(&quot;one&quot;, &quot;two&quot;, &quot;three&quot;))</span></span></code></pre></div><h3 id="str-interpret-as-string" tabindex="-1">str: interpret as string <a class="header-anchor" href="#str-interpret-as-string" aria-label="Permalink to &quot;str: interpret as string&quot;">​</a></h3> <div class="warning custom-block"><p class="custom-block-title">In-development feature</p> <p>Try this feature on <code>dev</code> (Docker image or branch). It will be finalized for version <code>5.0</code>.</p></div> <p>A quoted string in BCQL can be interpreted as either a string or a token query, depending on the context. For example, <code>&quot;duck&quot;</code> might mean <code>[word=&quot;duck&quot;]</code> (a query), or it might just mean the simple string value. When building a list of strings, BlackLab doesn&#39;t know which one you mean, so you need to explicitly tell it. For example, to create a list of strings <em>cat</em> and <em>dog</em>, use:</p> <div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>list(str(&quot;cat&quot;), str(&quot;dog&quot;))</span></span></code></pre></div><p>note that this is different from</p> <div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>list(&quot;cat&quot;, &quot;dog&quot;)</span></span></code></pre></div><p>which will create a list of token queries.</p> <h3 id="symbol-interpret-as-symbol" tabindex="-1">symbol: interpret as symbol <a class="header-anchor" href="#symbol-interpret-as-symbol" aria-label="Permalink to &quot;symbol: interpret as symbol&quot;">​</a></h3> <div class="warning custom-block"><p class="custom-block-title">In-development feature</p> <p>Try this feature on <code>dev</code> (Docker image or branch). It will be finalized for version <code>5.0</code>.</p></div> <p>To specify a symbol (e.g. an annotation) using a string:</p> <div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ symbol(&quot;word&quot;) = &quot;cow&quot; ]</span></span></code></pre></div><p>is equivalent to</p> <div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ word = &quot;cow&quot; ]</span></span></code></pre></div><p>For now, this mostly exists to prove that functions can return symbols, but it might prove useful in rare cases in the future.</p>`,150)])])}const m=t(i,[["render",n]]);export{h as __pageData,m as default};
